 major:{'RR Services':{wk:RR_H(6,22),sat:RR_H(7,21),sun:RR_H(7,21)},'First aid':{wk:RR_H(6,23),sat:RR_H(7,23),sun:RR_H(7,22)},'Pharmacy':{wk:RR_H(8,20),sat:RR_H(9,18),sun:null},'Police':{wk:RR_H(7,23),sat:RR_H(7,23),sun:RR_H(8,22)},'Mobility assistance':{wk:RR_H(6,22),sat:RR_H(7,21),sun:RR_H(7,21)},
  'Lost property':{wk:RR_H(9,17),sat:null,sun:null},'Café':{wk:RR_H(6,21),sat:RR_H(7,20),sun:RR_H(8,20)},'Left luggage':{wk:RR_H(7,21),sat:RR_H(8,20),sun:RR_H(8,20)}},
